// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {VaultAdapter} from "../src/VaultAdapter.sol";

contract InvMutTest is Test {
    VaultAdapter c;

    function setUp() public {
        c = new VaultAdapter();
    }

    function testFuzz_property(
        uint256 kink,
        uint256 slope0,
        uint256 slope1,
        address caller
    ) public {
        // kink must be strictly within (0, 1e27) per C's admissible domain
        kink = bound(kink, 1, 1e27 - 1);

        // access-control manager that grants every access request
        GrantAll manager = new GrantAll();

        // minimal ERC-1967 proxy pointing at the implementation,
        // because the implementation's constructor disables its own initializers
        Proxy proxy = new Proxy(address(c));

        // drive the difference through the public initialize entry point
        vm.prank(caller);
        try IInit(address(proxy)).initialize(address(manager)) {
            // initialization succeeded; now any gated call must consult the manager.
            // P stored it -> manager returns true -> success.
            // M stored nothing (0) -> checkAccess against empty address fails -> revert.
            vm.prank(caller);
            try IInit(address(proxy)).setSlopes(
                address(0xdead),
                IVaultAdapterLike.SlopeData(kink, slope0, slope1)
            ) {
                assertTrue(true, "gated call should succeed on reference");
            } catch {
                assertTrue(false, "setSlopes reverted after successful initialize");
            }
        } catch {
            assertTrue(false, "initialize must succeed on the reference contract");
        }
    }
}

interface IInit {
    function initialize(address _accessControl) external;

    function setSlopes(address _asset, IVaultAdapterLike.SlopeData memory _slopes) external;
}

interface IVaultAdapterLike {
    struct SlopeData {
        uint256 kink;
        uint256 slope0;
        uint256 slope1;
    }
}

contract GrantAll {
    function checkAccess(bytes4, address, address) external pure returns (bool) {
        return true;
    }
}

contract Proxy {
    address private immutable implementation;

    constructor(address _implementation) {
        implementation = _implementation;
    }

    fallback() external payable {
        address impl = implementation;
        assembly {
            calldatacopy(0, 0, calldatasize())
            let result := delegatecall(gas(), impl, 0, calldatasize(), 0, 0)
            returndatacopy(0, 0, returndatasize())
            switch result
            case 0 {
                revert(0, returndatasize())
            }
            default {
                return(0, returndatasize())
            }
        }
    }
}
